insert into public.tipos_laudo (id, codigo, nome, descricao, ordem, ativo) values
  ('186f97a3-3426-581c-a6eb-e4a44fc4bc11', 'administrativo', 'Administrativo (aptidão, licenças e capacidade laborativa)', 'Laudo médico-pericial administrativo — perícias no âmbito da Administração Pública federal, estadual ou municipal (exceto perícia previdenciária direta do INSS) e, quando cabível, em instituições privadas: aptidão para ingresso, capacidade laborativa, licença para tratamento de saúde / ex-officio / gestante / acompanhamento de familiar, readaptação funcional, retorno ao trabalho, nexo causal em acidente de trabalho, aposentadoria por incapacidade permanente, isenção de IR por doença grave, aposentadoria da PcD com estabelecimento do grau, candidato com alegada deficiência. Módulos condicionais por objeto administrativo (XV-A..J). O diagnóstico/CID não define incapacidade isoladamente — a conclusão decorre das manifestações clínicas e da relação com as atividades efetivamente exercidas.', 10, true);
