  ('b7749fd5-63f2-5240-a6bf-f5541eeb42f8', '186f97a3-3426-581c-a6eb-e4a44fc4bc11', 'exame_fisico_sistemas', 'XI — Exame Físico por Aparelhos e Sistemas', 12, false, null, null),
  ('0d98573c-cba6-51cc-9752-40f76c5c8d1a', '186f97a3-3426-581c-a6eb-e4a44fc4bc11', 'diagnosticos_condicoes', 'XII — Diagnósticos / Condições de Saúde', 13, false, null, null),
  ('9775bd74-1724-59e8-a6f3-570c0d2dc000', '186f97a3-3426-581c-a6eb-e4a44fc4bc11', 'analise_capacidade_laborativa', 'XIII — Análise da Capacidade Laborativa', 14, false, null, null),
  ('77434d86-bdcf-588d-8f31-00f39340dcea', '186f97a3-3426-581c-a6eb-e4a44fc4bc11', 'discussao', 'XIV — Discussão Médico-Pericial', 15, false, null, 'O(a) periciado(a) apresenta [condição/diagnóstico], manifestada atualmente por [achados clínicos e funcionais]. No exercício de sua função, desempenha efetivamente [tarefas], que exigem [demandas físicas/cognitivas]. Os achados médico-periciais demonstram [ausência/presença] de incompatibilidade entre o estado clínico atual e essas atividades, especificamente em razão de [fundamentação]. Assim, a capacidade laborativa encontra-se [preservada / total e temporariamente comprometida / total e permanentemente comprometida / parcialmente e temporariamente comprometida], observados os critérios da normativa administrativa aplicável.'),
  ('26de8add-b5f7-5e9e-9655-ba1d68f86b46', '186f97a3-3426-581c-a6eb-e4a44fc4bc11', 'modulo_ingresso', 'XV-A — Ingresso / Admissão', 16, true, '{"campo_codigo": "finalidade", "valores_gatilho": ["ingresso_admissao"]}'::jsonb, null),
