  ('7eed09a3-d212-5da5-8027-039c3bbdd5d0', 'a7e89fed-7c64-55e7-88ca-bda5a47497c9', null, 'modelo_conclusao', 'Modelo de conclusão', 'selecao_unica', 1, false, true, '[{"codigo": "capacidade_preservada", "rotulo": "Capacidade preservada", "texto_automatico": "À avaliação médico-pericial atual, as manifestações clínicas identificadas mostram-se compatíveis com as atividades efetivamente desempenhadas, não sendo demonstrado comprometimento da capacidade laborativa para a função analisada."}, {"codigo": "total_temporaria", "rotulo": "Total e temporária", "texto_automatico": "As manifestações clínicas atuais determinam comprometimento total e temporário da capacidade para as atividades efetivamente desempenhadas, estimando-se necessidade de afastamento por [___], com reavaliação em [___], observada a normativa aplicável."}, {"codigo": "parcial_temporaria_readaptacao", "rotulo": "Parcial temporária / readaptação", "texto_automatico": "Há comprometimento parcial da capacidade laborativa, permanecendo capacidade residual para [atividades], devendo ser evitadas [restrições], sendo tecnicamente cabível avaliação para readaptação funcional conforme a normativa institucional."}, {"codigo": "total_permanente", "rotulo": "Total e permanente", "texto_automatico": "Os achados demonstram comprometimento total e permanente da capacidade laborativa, sem perspectiva funcional suficiente de recuperação/readaptação para as atribuições consideradas, observados os critérios administrativos aplicáveis."}]'::jsonb, null, false, null, true),
